}

args.new_string:
	// Renew each period that has ended, in order, so that a job that ran late (or not at all) catches up period by period.
	anchor := billing.Anchor(sub)
	pastDue := false
	for !sub.CurrentPeriodEnd.After(now) {
		start := sub.CurrentPeriodEnd
		end := billing.PeriodEnd(anchor, plan.Interval, start)
		paid := true
		var err error
		switch {
		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		case plan.UsageType == store.Licensed:
			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
		}
		if err != nil {
			return err
		}
		// A declined period leaves the subscription past due until the end of this run, even if a later period is paid.
		pastDue = pastDue || !paid
		status := store.Active
		if pastDue {
			status = store.PastDue
		}
		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
			x.Status = status
			return nil
		})
		if err != nil {
			return err
		}
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	}
	return nil
}

