func TestMonthEndAnchorDoesNotDrift(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.Clock.Set(time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC))
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	ends := []time.Time{
		time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC),
		time.Date(2026, 4, 30, 10, 0, 0, 0, time.UTC),
		time.Date(2026, 5, 31, 10, 0, 0, 0, time.UTC),
	}
	if !sub.CurrentPeriodEnd.Equal(ends[0]) {
		t.Fatalf("first period ends %v, want %v", sub.CurrentPeriodEnd, ends[0])
	}
	for _, want := range ends[1:] {
		prevEnd := sub.CurrentPeriodEnd
		e.Clock.Set(prevEnd)
		if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
			t.Fatalf("RenewDue = %d, %v", n, err)
		}
		sub, _ = e.Store.Subscription(e.Acme.ID, sub.ID)
		if !sub.CurrentPeriodStart.Equal(prevEnd) || !sub.CurrentPeriodEnd.Equal(want) {
			t.Fatalf("period = [%v, %v), want [%v, %v)", sub.CurrentPeriodStart, sub.CurrentPeriodEnd, prevEnd, want)
		}
	}
}

func TestMissedRenewalsAreEachInvoiced(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.Clock.Set(time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC))
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	// The job did not run for two and a half months: the periods ending Feb 28 and Mar 31 have both ended, and Apr 30 has not.
	e.Clock.Set(time.Date(2026, 4, 15, 10, 0, 0, 0, time.UTC))
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if !got.CurrentPeriodStart.Equal(time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)) || !got.CurrentPeriodEnd.Equal(time.Date(2026, 4, 30, 10, 0, 0, 0, time.UTC)) {
		t.Fatalf("after the catch-up = [%v, %v)", got.CurrentPeriodStart, got.CurrentPeriodEnd)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	wantStarts := []time.Time{
		time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC),
		time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC),
		time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC),
	}
	if len(invs) != len(wantStarts) {
		t.Fatalf("invoices = %d, want %d: %+v", len(invs), len(wantStarts), invs)
	}
	for _, w := range wantStarts {
		found := false
		for _, inv := range invs {
			found = found || (inv.PeriodStart != nil && inv.PeriodStart.Equal(w))
		}
		if !found {
			t.Errorf("no invoice for the period starting %v", w)
		}
	}
	if n, _ := e.Subs.RenewDue(ctx); n != 0 {
		t.Fatalf("renewed again: %d", n)
	}
}
