		for _, inv := range invs {
			found = found || (inv.PeriodStart != nil && inv.PeriodStart.Equal(w))
		}
		if !found {
			t.Errorf("no invoice for the period starting %v", w)
		}
	}
	if n, _ := e.Subs.RenewDue(ctx); n != 0 {
		t.Fatalf("renewed again: %d", n)
	}
}
