README.md:13:| `internal/billing` | Invoice arithmetic (`Compute`) and billing periods (`AddInterval`). No state. |

1	// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
2	// renewing them when a billing period ends.
3	package subscriptions
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"time"
10	
11		"example.com/tally/internal/billing"
12		"example.com/tally/internal/clock"
13		"example.com/tally/internal/payments"
14		"example.com/tally/internal/store"
15	)
16	
17	// Errors.
18	var (
19		ErrPlanInactive = errors.New("the plan is not active")
20		ErrCanceled     = errors.New("the subscription is canceled")
21	)
22	
23	// Service runs subscriptions.
24	type Service struct {
25		Store     *store.Store
26		Payments  *payments.Service
27		Clock     clock.Clock
28		Publisher payments.Publisher // nil: no events
29	}
30	
31	// CreateInput is a new subscription.
32	type CreateInput struct {
33		CustomerID      string
34		PlanID          string
35		Quantity        int // 0 means 1
36		DiscountPercent int
37	}
38	
39	// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
40	// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
41	// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
42	func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
43		plan, ok := s.Store.Plan(orgID, in.PlanID)
44		if !ok {
45			return store.Subscription{}, store.ErrNotFound
46		}
47		if !plan.Active {
48			return store.Subscription{}, ErrPlanInactive
49		}
50		if in.Quantity == 0 {
51			in.Quantity = 1
52		}
53		now := s.Clock.Now()
54		sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
55			StartedAt: now, CurrentPeriodStart: now}
56		if plan.TrialDays > 0 {
57			end := now.AddDate(0, 0, plan.TrialDays)
58			sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
59		} else {
60			sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
61		}
62		sub, err := s.Store.CreateSubscription(sub, now)
63		if err != nil {
64			return store.Subscription{}, err
65		}
66		s.publish(ctx, orgID, "subscription.created", sub)
67		if sub.Status == store.Active && plan.UsageType == store.Licensed {
68			paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
69			if err != nil {
70				return sub, err
71			}
72			if !paid {
73				if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
74					return sub, err
75				}
76			}
77		}
78		return sub, nil
79	}
80	
81	// UpdateInput changes a subscription; nil fields stay as they are.
82	type UpdateInput struct {
83		PlanID   *string
84		Quantity *int
85	}
86	
87	// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
88	func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
89		if in.PlanID != nil {
90			p, ok := s.Store.Plan(orgID, *in.PlanID)
91			if !ok {
92				return store.Subscription{}, store.ErrNotFound
93			}
94			if !p.Active {
95				return store.Subscription{}, ErrPlanInactive
96			}
97		}
98		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
99			if sub.Status == store.Canceled {
100				return ErrCanceled
101			}
102			if in.PlanID != nil {
103				sub.PlanID = *in.PlanID
104			}
105			if in.Quantity != nil {
106				sub.Quantity = *in.Quantity
107			}
108			return nil
109		})
110		if err != nil {
111			return store.Subscription{}, err
112		}
113		s.publish(ctx, orgID, "subscription.updated", sub)
114		return sub, nil
115	}
116	
117	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
118	// subscription changes nothing.
119	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
120		now := s.Clock.Now()
121		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
122			if sub.Status == store.Canceled {
123				return nil
124			}
125			if atPeriodEnd {
126				sub.CancelAtPeriodEnd = true
127				return nil
128			}
129			sub.Status, sub.CanceledAt = store.Canceled, &now
130			return nil
131		})
132		if err != nil {
133			return store.Subscription{}, err
134		}
135		if sub.Status == store.Canceled {
136			s.publish(ctx, orgID, "subscription.canceled", sub)
137		} else {
138			s.publish(ctx, orgID, "subscription.updated", sub)
139		}
140		return sub, nil
141	}
142	
143	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
144	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
145	// period in advance, a metered plan bills the usage of the period that ended. When several periods have ended, each one is
146	// renewed in order with its own invoice. Period boundaries do not depend on when RenewDue runs. A declined charge makes the
147	// subscription past due. RenewDue returns how many subscriptions it renewed or canceled.
148	func (s *Service) RenewDue(ctx context.Context) (int, error) {
149		now := s.Clock.Now()
150		n := 0
151		for _, sub := range s.Store.DueSubscriptions(now) {
152			if err := ctx.Err(); err != nil {
153				return n, err
154			}
155			if err := s.renew(ctx, sub, now); err != nil {
156				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
157			}
158			n++
159		}
160		return n, nil
161	}
162	
163	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
164		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
165		if !ok {
166			return store.ErrNotFound
167		}
168		if sub.CancelAtPeriodEnd {
169			end := sub.CurrentPeriodEnd
170			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
171				x.Status, x.CanceledAt = store.Canceled, &end
172				return nil
173			})
174			if err == nil {
175				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
176			}
177			return err
178		}
179		// Renew each period that has ended, in order, so that a job that ran late (or not at all) catches up period by period.
180		anchor := billing.Anchor(sub)
181		pastDue := false
182		for !sub.CurrentPeriodEnd.After(now) {
183			start := sub.CurrentPeriodEnd
184			end := billing.PeriodEnd(anchor, plan.Interval, start)
185			paid := true
186			var err error
187			switch {
188			case plan.UsageType == store.Metered && sub.Status != store.Trialing:
189				paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
190			case plan.UsageType == store.Licensed:
191				paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
192			}
193			if err != nil {
194				return err
195			}
196			// A declined period leaves the subscription past due until the end of this run, even if a later period is paid.
197			pastDue = pastDue || !paid
198			status := store.Active
199			if pastDue {
200				status = store.PastDue
201			}
202			sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
203				x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
204				x.Status = status
205				return nil
206			})
207			if err != nil {
208				return err
209			}
210			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
211		}
212		return nil
213	}
214	
215	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
216	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
217	// payment method stays open and counts as paid here (it is paid by hand).
218	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
219		var lines []store.Line
220		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
221		switch plan.UsageType {
222		case store.Licensed:
223			if plan.UnitAmount > 0 {
224				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
225			}
226		case store.Metered:
227			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
228				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
229			}
230		}
231		ps, pe := start, end
232		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
233			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
234		if err != nil {
235			return false, err
236		}
237		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
238		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
239		var decline *payments.DeclineError
240		switch {
241		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
242			return true, nil
243		case errors.As(err, &decline):
244			return false, nil
245		default:
246			return false, err
247		}
248	}
249	
250	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
251		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
252			x.Status = st
253			return nil
254		})
255		if err == nil {
256			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
257		}
258		return sub, err
259	}
